import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).split("\r?\n", -1)[1];
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        int answer = -1;
        for (int i = 0; i < s.length(); i++)
            if (counts[s.charAt(i) - 'a'] == 1) {
                answer = i + 1;
                break;
            }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	s := strings.TrimSuffix(strings.Split(string(raw), "\n")[1], "\r")
	var counts [26]int
	for i := 0; i < len(s); i++ {
		counts[s[i]-'a']++
	}
	answer := -1
	for i := 0; i < len(s); i++ {
		if counts[s[i]-'a'] == 1 {
			answer = i + 1
			break
		}
	}
	fmt.Println(answer)
}
